# open_timeout/read_timeout are constructor parameters, not CLI flags --
# SYNCBOX-SPEC.md only requires *some* bounded timeout on network
# operations, not that it be user-configurable. Callers (specs, mainly)
# can still tighten them to keep a deliberately-unresponsive test server
# fast to detect.
def initialize(server:, open_timeout: 5, read_timeout: 10)
  @base_uri = URI.parse(server)
  unless @base_uri.is_a?(URI::HTTP) && @base_uri.host
    raise ArgumentError, "invalid --server URL: #{server.inspect}"
  end

  @open_timeout = open_timeout
  @read_timeout = read_timeout
end

